@Test
    public void collapseRemovesChildItems() {
        DataObserver observer = registerMockDataObserver();
        mTreeAdapter.setExpanded(2, false);
        verify(observer).onItemRangeRemoved(9, 3);
        verifyNoMoreInteractions(observer);
    }

